<template>
  <div class="sfgl_child">
    <el-button @click="goback" size="mini" style="margin: 12px;">返回</el-button>
    <div class="sfpzs">
      <el-form ref="form" :model="form" :rules="rules" size="mini" label-width="110px">
        <el-form-item label="任务名称" style="padding-top: 16px;" prop="conf_name">
          <el-input v-model="form.conf_name" style="width: 50%;float: left;"></el-input>
          <div class="w-1\2" style="color: red;">*例:报警设备_解析类型名称</div>
        </el-form-item>
        <el-form-item label="单位名称" prop="Mine_id">
          <el-select v-model="form.Mine_id" placeholder="请选择单位名称" size="small" clearable filterable
            style="width: 50%;float: left;">
            <el-option v-for="item in options1" :key="item.id" :label="item.mine_name" :value="item.id"></el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="报警设备" prop="equipment_name">
          <!-- <el-cascader v-model="form.equipment_name" :options="dict.equipment_list" :props="props" clearable filterable style="width: 50%;float: left;" @change="handleChangeCanvas2();updateConfName();type_qy=true;"></el-cascader> -->
          <el-cascader v-model="form.equipment_name" :options="dict.equipment_list" :props="props" clearable filterable
            @change="addfn(1)" style="width: 50%;float: left;"></el-cascader>
        </el-form-item>
        <el-form-item label="解析类型" v-if="form.equipment_name" v-for="(item, index) in jxlxlist" :key="index">
          <el-select v-model="item.Algorithm_library_id" placeholder="请选择解析类型" @change="countfns(index)"
            filterable style="width: 50%;float: left;margin-right: 12px;">
            <el-option v-for="item in dict.algorithm_list" :key="item.id" :label="item.algorithm_name" :value="item.id">
            </el-option>
          </el-select>
          <div class="w-1\2">
            <el-button v-if="index == 0" icon="el-icon-plus" circle size="mini" @click="addfn"></el-button>
            <el-button icon="el-icon-minus" v-if="jxlxlist.length > 1" circle size="mini"
              @click="deletefn(index)"></el-button>
          </div>
        </el-form-item>
        <el-divider></el-divider>
        <div class="btnlist" v-if="jxlxlist.length > 0 && jxlxlist[0].algorithm_name">
          <div v-for="(item, index) in jxlxlist" v-show="item.algorithm_name" :key="index+'i'"
            :class="[{ is_active: btnCli+'i' == index+'i' }]" @click="btnClick(index)">{{ item.algorithm_name }}</div>
        </div>
        <div v-if="aaas">

          <div style="height:1024px;overflow: hidden;" v-for="(item,index) in jxlxlist" :key="item.id" v-show="index == btnCli">
            <cavdiv ref="canvasRef" :item="item" :conf_id="conf_ids" :indexnum="index" :types="ddds" v-if="jxlxlist[index].algorithm_name" @update:item="item[index] = $event"></cavdiv>
          </div>
        </div>
        <el-form-item>
          <div style="text-align: -end;margin-bottom: 24px;">
            <el-button type="primary" @click="sub_fn">保存</el-button>
            <el-button @click="goback">取消</el-button>
          </div>
        </el-form-item>
      </el-form>
    </div>
  </div>
</template>

<script>
import cavdiv from './sfgl_childsCom.vue'
export default {
  components: {
    cavdiv
  },
  name: "sfgl_child",
  data() {
    return {
      ddds: 0,
      aaas: true,
      conf_ids:'',
      btnCli: 0,
      listMap: [],
      jxlxlist: [],
      dict: [],
      options1: [],
      options2: [],
      options3: [],
      modelOptions: [],
      props: {
        checkStrictly: false,
        emitPath: false,
        value: "id",
        label: "equipment_name",
      },
      modelProps: {
        checkStrictly: false,
        emitPath: false,
        value: 'model_id', // 动态选择值字段
        label: 'model_type_name', // 动态选择标签字段
        // children: "children" // 如果子级还有下一级，确保正确指向子选项数组
      },
      form: {
        conf_name: '',
        Mine_id: '',
        equipment_name: '',
      },
      rules:{
        conf_name: [
          { required: true, message: '请输入任务名称', trigger: 'blur' },
        ],
        Mine_id: [
          { required: true, message: '请选择单位名称', trigger: 'change' },
        ],
        equipment_name: [
          { required: true, message: '请选择报警设备', trigger: 'change' },
        ],
      }
    };
  },
  computed: {

  },
  created() {

  },
  methods: {
    btnClick(index) {
      this.btnCli = index
    },
    addfn(e) {
      if(e == 1){
        this.jxlxlist = []
        this.jxlxlist.push({
          equipment_name: this.form.equipment_name,
          "Mine_id": "",
          "Equipment_id": "",
          "conf_area": '[]',
          "shield_status": "",
          "tem_conf_area": '[]',
          "draw_type": "1",
          "img_resolution": "",
          "image_draw_type": 1,
          "template_list_area": '[]',
          priority: "",
          run_time: "",
          mine_name: "",
          algorithm_name: "",
          Algorithm_library_id: "",
          type: 0,
          confidence: "60",
          tem_frames: "[27,37]",
          duration_time: 10,
          interval_time: 300,
          sensitivity: 25,
          defense_time_start: '00:00:00',
          defense_time_end: '23:59:59',
          image_count: 5,
          template_data: '[]',
          test_type_id: "",
          label_list: '[]',
          amp: 10,
          alg_select_type: '3',
          model_two_data: '[]',
          model_two_type: '',
        })
      }else if (this.jxlxlist.length < 3) {
        this.jxlxlist.push({
          equipment_name: this.form.equipment_name,
          "Mine_id": "",
          "Equipment_id": "",
          "conf_area": '[]',
          "shield_status": "",
          "tem_conf_area": '[]',
          "draw_type": "1",
          "img_resolution": "",
          "image_draw_type": 1,
          "template_list_area": '[]',
          priority: "",
          run_time: "",
          mine_name: "",
          algorithm_name: "",
          Algorithm_library_id: "",
          type: 0,
          confidence: "60",
          tem_frames: "[27,37]",
          duration_time: 10,
          interval_time: 300,
          sensitivity: 25,
          defense_time_start: '00:00:00',
          defense_time_end: '23:59:59',
          image_count: 5,
          template_data: '[]',
          test_type_id: "",
          label_list: '[]',
          amp: 10,
          alg_select_type: '3',
          model_two_data: '[]',
          model_two_type: '',
        })
      }
    },
    deletefn(e) {
      this.btnCli = 0
      this.jxlxlist.splice(e, 1);
      this.$refs.canvasRef[e].form.label_list=[]
      this.$refs.canvasRef[e].handleChangeSf(this.jxlxlist[e].Algorithm_library_id)
    },
    countfns(index) {
      this.btnCli = index
      this.jxlxlist[index].algorithm_name = null;
      this.jxlxlist[index].label_list = [];
      for (var i = 0; i < this.dict.algorithm_list.length; i++) {
        if (this.dict.algorithm_list[i].id == this.jxlxlist[index].Algorithm_library_id) {
          this.jxlxlist[index].Algorithm_library_id = this.dict.algorithm_list[i].id;
          this.jxlxlist[index].algorithm_name = this.dict.algorithm_list[i].algorithm_name;
          this.$refs.canvasRef[index].clearss(this.dict.algorithm_list[i].id)
          // this.ssa(index)
          // this.jxlxlist[index] = {
          //   equipment_name: this.dict.algorithm_list[i].algorithm_name,
          //   "Mine_id": "",
          //   "Equipment_id": "",
          //   "conf_area": '[]',
          //   "shield_status": "",
          //   "tem_conf_area": '[]',
          //   "draw_type": "1",
          //   "img_resolution": "",
          //   "image_draw_type": 1,
          //   "template_list_area": '[]',
          //   priority: "",
          //   run_time: "",
          //   mine_name: "",
          //   algorithm_name: "",
          //   Algorithm_library_id: this.dict.algorithm_list[i].Algorithm_library_id,
          //   type: 0,
          //   confidence: "60",
          //   tem_frames: "[27,37]",
          //   duration_time: 10,
          //   interval_time: 300,
          //   sensitivity: 25,
          //   defense_time_start: '00:00:00',
          //   defense_time_end: '23:59:59',
          //   image_count: 5,
          //   template_data: '[]',
          //   test_type_id: "",
          //   label_list: '[]',
          //   amp: 10,
          //   alg_select_type: '3',
          //   model_two_data: '[]',
          //   model_two_type: '',
          // }
        }
      }
    },
    goback() {
      this.$router.push({
        path: '/sfgl',
      })
    },
    sub_fn() {
      
      this.$refs['form'].validate((valid) => {
          if (valid) {
      // console.log(this.$refs.canvasRef);
      // this.$refs.canvasRef.setF()
      for(var i=0;i<this.jxlxlist.length;i++){
        this.$refs.canvasRef[i].sub_fn()
      }
      var objmap = {
        conf_name: this.form.conf_name,
        Mine_id: this.form.Mine_id,
        id: this.$route.query.id,
        equipment_name: this.form.equipment_name,
        model_data: this.jxlxlist,
      }
      console.log(objmap);
        console.log(this.jxlxlist)
        if(this.$route.query.map){
          this.$http
            .post(this.$url.url_5000 + "/model_view/algorithm_update_models", objmap)
            .then((response) => {
              // console.log(response);
              if (response.data.code === 200) {
                this.$message({
                  message: response.data.msg,
                  type: "success",
                });
                this.goback()
                // this.axioss();
                // this.handleClose();
              } else {
                this.$message({
                  message: response.data.msg,
                  type: "warning",
                });
              }
            })
            .catch(function (response) {
              console.log(response);
            });
        }else{
          this.$http
            .post(this.$url.url_5000 + "/model_view/algorithm_add_models", objmap)
            .then((response) => {
              // console.log(response);
              if (response.data.code === 200) {
                this.$message({
                  message: response.data.msg,
                  type: "success",
                });
                this.goback()
                // this.axioss();
                // this.handleClose();
              } else {
                this.$message({
                  message: response.data.msg,
                  type: "warning",
                });
              }
            })
            .catch(function (response) {
              console.log(response);
            });
        }
        } else {
                this.$message({
                  message: '算法配置数据有未填写项',
                  type: "warning",
                });
          }
        });
    },
    init() {//字典
      this.$http
        .get(
          this.$url.url_5000 + "/model_view/type_select",
          {
            params: {
              mine_id: '',
              type: 1
            },
          },
          {
            withCredentials: true,
          }
        )
        .then((response) => {
          if (response.data.code === 200) {
            this.dict = response.data;
            this.options1 = response.data.mine_list;
            // this.form.Mine_id = response.data.mine_list[0].id
            this.options2 = response.data.equipment_list;
            this.options3 = response.data.algorithm_list;
            this.modelOptions = response.data.model_type_template.map(v => {
              return {
                ...v,
                model_id: 'F' + v.id,
                children: v.template_model_data_list.map(child => {
                  return {
                    ...child,
                    model_id: child.id,
                    model_type_name: child.model_name
                  }
                })
              }
            })
            // console.log(9527,this.modelOptions)
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
  },
  mounted() {
    this.init()
    if(this.$route.query.map){
      var obj = JSON.parse(this.$route.query.map)
      this.conf_ids = this.$route.query.id
      this.form = obj
      this.jxlxlist = obj.model_data
      this.jxlxlist.forEach(item =>{
        if(!Array.isArray(item.label_list)){
          item.label_list = JSON.parse(item.label_list)
        }
      })
    }
  },
  beforeDestroy() {

  },
  destroyed() {

  },
};
</script>

<style lang="scss" scoped>
.is_active {
  background-color: #ecf5ff !important;
  border-color: #d9ecff !important;
  color: #409EFF !important;
}

.btnlist {
  width: 100%;
  height: 40px;

  div {
    width: 100px;
    height: 80%;
    float: left;
    margin-right: 12px;
    display: flex;
    align-items: center;
    font-size: 12px;
    justify-content: center;
    color: #858585;
    cursor: pointer;
    border: 1px solid #ebebeb;
    border-radius: 5px;
  }
}

.sfgl_child {
  width: 100%;
  height: 100%;
  background: #fff;
  overflow: hidden;
  overflow-y: scroll;
}

.sfpzs {
  width: 900px;
  height: calc(100% - 100px);
  margin: 0 auto;
}

.w-1\2 {
  width: calc(50% - 12px) !important;
  margin-left: 12px !important;
  float: left;
}

.jia_div {
  width: 640px;
  height: 360px;
  text-align: center;
  color: red;
  display: flex;
  align-items: center;
  justify-content: center;
}

.Bcanvas {
  width: 100%;
  height: calc(100% - 50px);
  border: 1px solid #e5e5e5;
  box-sizing: border-box;
  -moz-box-sizing: border-box;
  /* margin-left: 100px;
        margin-top: 15px; */
}

.canvasBtn {
  /* margin-left: 100px; */
  width: 100%;
  height: 39px;
  text-align: center;
  background: rgba(203, 203, 203, 0.2);
  border-radius: 0px 0px 4px 4px;

  .el-button {
    color: rgba(0, 0, 0, 0.6);
    margin-left: 24px;
  }

  .el-button:hover {
    color: #409eff;
  }
}

#mycanvas,
#mycanvas1,
#mycanvas2,
#mycanvas3 {
  width: 640px;
  height: 360px;
  position: relative;
  top: -100%;
  left: 0;
  z-index: 10;
}
</style>
